// ==UserScript==
// @name         Cosmetic filters (Omarchy)
// @description  Hides the elements the filter lists name for this site (uBlock Origin's cosmetic half). qutebrowser's own adblock can only refuse requests; the reserved ad boxes and sponsored teasers a publisher keeps in its own markup stay visible without this.
// @namespace    https://github.com/Maximilian-Maag/omarchy-qutebrowser
// @version      1
// @match        *://*/*
// @run-at       document-start
// @grant        none
// ==/UserScript==

// The rule table below is GENERATED by tools/build_cosmetic.py from the same filter lists
// config.py subscribes to — do not edit by hand. It holds only the *cosmetic* half
// (`domain##selector`) and only rules that are plain CSS: a network rule (`||…`, `$…`) is
// qutebrowser's job, and a procedural filter (`:has-text(`, `:style(`, `-abp-`) cannot be
// expressed as CSS at all. Generic rules (`##selector`, no domain) are left out on purpose:
// without uBlock's generic-exception machinery they are the ones that break sites.
//
// It is one flat string, one record per line: `<domain>\t<selector>\t<selector>…`. An object
// literal of the same rules cost a ~31k-array, ~64k-string object graph on EVERY page,
// built before the first paint; a string is only tokenised, and a page needs the records of
// its own host and its parents, which is two or three substring searches.
var COSMETIC_BLOB = "";  // @data

// ── pure helpers (sliced out and tested by tests/js/cosmetic-filters.test.js) ──
function cosmeticHosts(host) {
  var out = [];
  var parts = String(host || '').toLowerCase().split('.');
  for (var i = 0; i < parts.length; i++) {
    var labels = parts.slice(i);
    if (labels.length < 2) { break; }   // a bare TLD or an empty host is not a site
    out.push(labels.join('.'));
  }
  return out;
}

function cosmeticSelectors(host, blob) {
  var out = [];
  var seen = {};
  if (!blob) { return out; }
  cosmeticHosts(host).forEach(function (candidate) {
    // The record starts with a newline and ends with one, so `b.example.org` can never be
    // found inside `a.b.example.org`, and a domain that is a prefix of another cannot
    // borrow its rules.
    var at = blob.indexOf('\n' + candidate + '\t');
    if (at === -1) { return; }
    var from = at + candidate.length + 2;
    var end = blob.indexOf('\n', from);
    blob.slice(from, end === -1 ? blob.length : end).split('\t').forEach(function (selector) {
      if (selector && !seen[selector]) { seen[selector] = true; out.push(selector); }
    });
  });
  return out;
}

// document.head exists once the page has a <head>; at document-start it may not, and
// documentElement always does. Keeping this as a helper lets the test pin which one wins.
function cosmeticParent(doc) {
  return doc.head || doc.documentElement || null;
}

function cosmeticCss(selectors) {
  return selectors.map(function (selector) {
    return selector + '{display:none !important;}';
  }).join('\n');
}

// ── the page side ──
(function () {
  'use strict';
  function inject() {
    try {
      var css = cosmeticCss(cosmeticSelectors(location.hostname, COSMETIC_BLOB));
      if (!css) { return; }
      var style = document.createElement('style');
      style.id = 'omarchy-cosmetic-filters';
      style.textContent = css;
      var parent = cosmeticParent(document);
      if (!parent) { return; }
      parent.appendChild(style);
    } catch (e) { /* a page that will not take a stylesheet is not worth breaking */ }
  }
  if (document.head) { inject(); }
  else { document.addEventListener('DOMContentLoaded', inject); }
})();
